import json, itertools
p='/root/.openclaw/agents/main/sessions/item-2570.jsonl'
with open(p,encoding='utf-8') as f:
 for i,line in zip(range(1,20), f):
  try: o=json.loads(line)
  except Exception as e: print(i,'bad',e); continue
  print('\nLINE',i,'keys',list(o.keys()))
  def summar(v,indent=0):
   if indent>2: return
   if isinstance(v,dict):
    for k,val in list(v.items())[:20]:
     if isinstance(val,str): print('  '*indent,k,'str',len(val),repr(val[:80]))
     elif isinstance(val,(list,dict)): print('  '*indent,k,type(val).__name__,len(val)); summar(val,indent+1)
     else: print('  '*indent,k,type(val).__name__,repr(val)[:80])
   elif isinstance(v,list):
    for idx,val in enumerate(v[:5]):
     print('  '*indent,'[{}]'.format(idx),type(val).__name__); summar(val,indent+1)
  summar(o)
