python3 - <<'PY'
from pathlib import Path
import unicodedata, hashlib, json
p=Path('/root/.openclaw/workspace/system-prompt-built.txt')
b=p.read_bytes()
report={}
# UTF-8 strict decode
try:
    s=b.decode('utf-8','strict')
    report['utf8Strict']='ok'
except UnicodeDecodeError as e:
    report['utf8Strict']='error'
    report['utf8Error']={'start':e.start,'end':e.end,'reason':e.reason}
    s=b.decode('utf-8','replace')
report['bytes']=len(b)
report['sha256']=hashlib.sha256(b).hexdigest()
report['codepoints']=len(s)
report['lines']=s.count('\n')+1
report['bomAtStart']=s.startswith('\ufeff')
report['replacementChars']=s.count('\ufffd')
# Unicode version from Python database
report['unicodedataVersion']=unicodedata.unidata_version

def is_noncharacter(cp):
    return (0xFDD0 <= cp <= 0xFDEF) or (cp & 0xFFFE) == 0xFFFE and cp <= 0x10FFFF

def cat(ch): return unicodedata.category(ch)
issues=[]
counts={}
for idx,ch in enumerate(s):
    cp=ord(ch)
    c=cat(ch)
    counts[c]=counts.get(c,0)+1
    name=unicodedata.name(ch,'<unassigned>')
    line=s.count('\n',0,idx)+1
    col=idx-(s.rfind('\n',0,idx)+1)+1
    def add(kind,severity='warn'):
        issues.append({'kind':kind,'severity':severity,'index':idx,'line':line,'col':col,'cp':f'U+{cp:04X}','char':ch,'category':c,'name':name})
    if 0xD800 <= cp <= 0xDFFF: add('surrogate','error')
    if cp > 0x10FFFF: add('above-unicode-range','error')
    if is_noncharacter(cp): add('noncharacter','error')
    if ch=='\ufffd': add('replacement-character','error')
    # Controls except accepted whitespace tab/newline/CR
    if c=='Cc' and ch not in '\t\n\r': add('control-character','warn')
    # Format chars with known prompt/security implications
    if c=='Cf': add('format-character','info')
    if 0x202A <= cp <= 0x202E or 0x2066 <= cp <= 0x2069: add('bidi-control','error')
    if cp in (0x200B,0x200C,0x200D,0xFEFF): add('zero-width-or-bom','warn')
    if cp in (0x00A0,0x2007,0x202F): add('non-breaking-space','info')
# normalization checks
for form in ['NFC','NFD','NFKC','NFKD']:
    report[f'is{form}']=unicodedata.is_normalized(form,s)
report['categoryCounts']=dict(sorted(counts.items()))
# collect unique non-ascii and names
unique=[]; seen=set()
for ch in s:
    cp=ord(ch)
    if cp>127 and cp not in seen:
        seen.add(cp); unique.append({'cp':f'U+{cp:04X}','char':ch,'category':cat(ch),'name':unicodedata.name(ch,'<unassigned>')})
report['uniqueNonAsciiCount']=len(unique)
report['uniqueNonAscii']=unique
report['issues']=issues
report['issueSummary']={}
for it in issues:
    key=it['kind']; report['issueSummary'][key]=report['issueSummary'].get(key,0)+1
# write detailed JSON
